import axios from "axios";

export const apiClient = axios.create({
  baseURL: process.env.NEXT_PUBLIC_API_URL ?? "http://localhost:3001",
  withCredentials: false,
});

// Inject Bearer token from sessionStorage on client side
if (typeof window !== "undefined") {
  apiClient.interceptors.request.use((config) => {
    const token = sessionStorage.getItem("accessToken");
    if (token) config.headers.Authorization = `Bearer ${token}`;
    return config;
  });
}

export type ApiError = { message: string; statusCode: number };

import axios from "axios";

export const apiClient = axios.create({
  baseURL: process.env.NEXT_PUBLIC_API_URL ?? "http://localhost:3001",
  withCredentials: false,
});

// Inject Bearer token from sessionStorage on client side
if (typeof window !== "undefined") {
  apiClient.interceptors.request.use((config) => {
    const token = sessionStorage.getItem("accessToken");
    if (token) config.headers.Authorization = `Bearer ${token}`;
    return config;
  });

  let isRefreshing = false;
  let queue: Array<{ resolve: (token: string) => void; reject: (err: unknown) => void }> = [];

  function processQueue(err: unknown, token: string | null) {
    queue.forEach((p) => (err ? p.reject(err) : p.resolve(token!)));
    queue = [];
  }

  apiClient.interceptors.response.use(
    (res) => res,
    async (error) => {
      const original = error.config;

      // Only handle 401, skip refresh endpoint itself to avoid loops
      if (error.response?.status !== 401 || original._retry || original.url?.includes("/auth/")) {
        return Promise.reject(error);
      }

      const refreshToken = sessionStorage.getItem("refreshToken");
      if (!refreshToken) {
        sessionStorage.clear();
        window.location.replace("/login");
        return Promise.reject(error);
      }

      if (isRefreshing) {
        // Queue concurrent requests while refresh is in progress
        return new Promise((resolve, reject) => {
          queue.push({
            resolve: (token) => {
              original.headers.Authorization = `Bearer ${token}`;
              resolve(apiClient(original));
            },
            reject,
          });
        });
      }

      original._retry = true;
      isRefreshing = true;

      try {
        const { data } = await axios.post<{ accessToken: string; refreshToken: string }>(
          `${process.env.NEXT_PUBLIC_API_URL ?? "http://localhost:3001"}/auth/refresh`,
          { refreshToken },
        );

        sessionStorage.setItem("accessToken", data.accessToken);
        sessionStorage.setItem("refreshToken", data.refreshToken);

        apiClient.defaults.headers.common.Authorization = `Bearer ${data.accessToken}`;
        processQueue(null, data.accessToken);

        original.headers.Authorization = `Bearer ${data.accessToken}`;
        return apiClient(original);
      } catch (refreshErr) {
        processQueue(refreshErr, null);
        sessionStorage.clear();
        window.location.replace("/login");
        return Promise.reject(refreshErr);
      } finally {
        isRefreshing = false;
      }
    },
  );
}

export type ApiError = { message: string; statusCode: number };

"use client";

import { useState, useEffect } from "react";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { format } from "date-fns";
import {
  getWorkouts, startWorkout, finishWorkout, logSets,
  type WorkoutSession, type CreateSetInput,
} from "@/features/workouts/workouts.api";
import { getExercises } from "@/features/exercises/exercises.api";
import { T, CAT_COLOR, Icon, FmBadge, FmBtn, FmPageLoader, FmEmpty, FmExercisePicker, AppHeader } from "@/components/fm";
import { useLang, useT } from "@/lib/lang-context";

// ─── Elapsed timer hook ────────────────────────────────────────────────────────
function useElapsed(startedAt: string) {
  const [elapsed, setElapsed] = useState(() =>
    Math.floor((Date.now() - new Date(startedAt).getTime()) / 1000)
  );
  useEffect(() => {
    const t = setInterval(() => setElapsed((s) => s + 1), 1000);
    return () => clearInterval(t);
  }, []);
  const mm = String(Math.floor(elapsed / 60)).padStart(2, "0");
  const ss = String(elapsed % 60).padStart(2, "0");
  return `${mm}:${ss}`;
}

// ─── Set Logger ────────────────────────────────────────────────────────────────
function SetLogger({ session, onDone }: { session: WorkoutSession; onDone: () => void }) {
  const qc = useQueryClient();
  const elapsed = useElapsed(session.startedAt);
  const { lang } = useLang();
  const t = useT();

  const [exerciseId, setExerciseId] = useState("");
  const [rows, setRows] = useState<Omit<CreateSetInput, "exerciseId">[]>([
    { setNumber: 1, reps: undefined, weight: undefined },
  ]);

  const { data: exData } = useQuery({
    queryKey: ["exercises-all", lang],
    queryFn: () => getExercises({ limit: 100, lang }),
    staleTime: Infinity,
  });
  const exercises = (exData?.items ?? []).map((ex) => ({
    ...ex,
    name: lang === "ru" ? (ex.nameRu ?? ex.name) : ex.name,
  }));

  function handleExerciseChange(id: string) {
    setExerciseId(id);
    const existing = session.sets.filter((s) => s.exercise.id === id).length;
    setRows([{ setNumber: existing + 1, reps: undefined, weight: undefined }]);
  }

  const { mutate: log, isPending: logging } = useMutation({
    mutationFn: () => logSets(session.id, rows.map((r) => ({ ...r, exerciseId }))),
    onSuccess: (data) => {
      const maxSet = data.length > 0 ? Math.max(...data.map((s) => s.setNumber)) : rows.length;
      setRows([{ setNumber: maxSet + 1, reps: undefined, weight: undefined }]);
      qc.invalidateQueries({ queryKey: ["workouts"] });
      qc.invalidateQueries({ queryKey: ["dashboard-stats"] });
    },
  });

  const { mutate: finish, isPending: finishing } = useMutation({
    mutationFn: () => finishWorkout(session.id),
    onSuccess: () => {
      qc.invalidateQueries({ queryKey: ["workouts"] });
      qc.invalidateQueries({ queryKey: ["dashboard-stats"] });
      onDone();
    },
  });

  function addRow() {
    const existing = session.sets.filter((s) => s.exercise.id === exerciseId).length;
    setRows((r) => [...r, { setNumber: existing + r.length + 1, reps: undefined, weight: undefined }]);
  }

  function updateRow(i: number, key: "reps" | "weight", val: string) {
    setRows((r) => r.map((row, idx) =>
      idx === i ? { ...row, [key]: val === "" ? undefined : Number(val) } : row
    ));
  }

  const canLog = !!exerciseId && rows.some((r) => r.reps != null || r.weight != null);

  return (
    <div style={{ background: T.bgCard, borderRadius: 16, border: `1px solid ${T.border}`, overflow: "hidden" }}>
      {/* Session header */}
      <div style={{ padding: "14px 18px", borderBottom: `1px solid ${T.border}`, display: "flex", alignItems: "center", justifyContent: "space-between" }}>
        <div>
          <div style={{ display: "flex", alignItems: "center", gap: 6, marginBottom: 2 }}>
            <div style={{ width: 8, height: 8, borderRadius: "50%", background: T.success, animation: "fm-pulse 2s infinite" }} />
            <span style={{ fontFamily: "var(--font-barlow-condensed, sans-serif)", fontSize: 13, fontWeight: 700, color: T.success, textTransform: "uppercase", letterSpacing: "0.08em" }}>
              {t.workouts.active}
            </span>
          </div>
          <span style={{ fontFamily: "var(--font-barlow-condensed, sans-serif)", fontSize: 26, fontWeight: 900, color: T.textPrimary, letterSpacing: "-0.01em" }}>
            {elapsed}
          </span>
        </div>
        <FmBtn variant="danger" size="sm" loading={finishing} onClick={() => finish()}>
          {t.workouts.finish}
        </FmBtn>
      </div>

      <div style={{ padding: "14px 18px", display: "flex", flexDirection: "column", gap: 14 }}>
        <FmExercisePicker value={exerciseId} onChange={handleExerciseChange} exercises={exercises} />

        {exerciseId && (
          <div>
            <div style={{ display: "grid", gridTemplateColumns: "36px 1fr 1fr", gap: 6, marginBottom: 6 }}>
              {[t.workouts.setCol, t.workouts.repsCol, "kg"].map((h) => (
                <span key={h} style={{ textAlign: "center", fontSize: 10, color: T.textMuted, fontFamily: "var(--font-barlow-condensed, sans-serif)", fontWeight: 700, letterSpacing: "0.08em", textTransform: "uppercase" }}>
                  {h}
                </span>
              ))}
            </div>
            {rows.map((row, i) => (
              <div key={i} style={{ display: "grid", gridTemplateColumns: "36px 1fr 1fr", gap: 6, marginBottom: 6 }}>
                <div style={{ height: 42, background: T.bgInput, borderRadius: 8, display: "flex", alignItems: "center", justifyContent: "center" }}>
                  <span style={{ fontFamily: "var(--font-barlow-condensed, sans-serif)", fontSize: 15, fontWeight: 800, color: T.textSub }}>{row.setNumber}</span>
                </div>
                <input type="number" min={0} placeholder="—" value={row.reps ?? ""} onChange={(e) => updateRow(i, "reps", e.target.value)} style={{ height: 42, background: T.bgInput, border: `1.5px solid ${T.border}`, borderRadius: 8, textAlign: "center", color: T.textPrimary, fontFamily: "var(--font-barlow-condensed, sans-serif)", fontSize: 17, fontWeight: 700, outline: "none" }} />
                <input type="number" min={0} step={0.5} placeholder="—" value={row.weight ?? ""} onChange={(e) => updateRow(i, "weight", e.target.value)} style={{ height: 42, background: T.bgInput, border: `1.5px solid ${T.border}`, borderRadius: 8, textAlign: "center", color: T.textPrimary, fontFamily: "var(--font-barlow-condensed, sans-serif)", fontSize: 17, fontWeight: 700, outline: "none" }} />
              </div>
            ))}
            <button type="button" onClick={addRow} disabled={!exerciseId} style={{ background: "none", border: "none", color: T.accent, fontFamily: "var(--font-dm-sans, sans-serif)", fontSize: 12, fontWeight: 500, cursor: "pointer", padding: "2px 0", opacity: exerciseId ? 1 : 0.4 }}>
              {t.workouts.addSet}
            </button>
          </div>
        )}

        <FmBtn onClick={() => log()} disabled={!canLog} loading={logging} style={{ width: "100%" }}>
          {t.workouts.logSets}
        </FmBtn>

        {session.sets.length > 0 && (
          <div style={{ borderTop: `1px solid ${T.border}`, paddingTop: 12 }}>
            <span style={{ fontSize: 10, fontFamily: "var(--font-barlow-condensed, sans-serif)", fontWeight: 700, textTransform: "uppercase", letterSpacing: "0.08em", color: T.textMuted }}>
              {t.workouts.logged} · {session.sets.length}
            </span>
            <div style={{ marginTop: 8, display: "flex", flexDirection: "column", gap: 5 }}>
              {session.sets.map((s) => (
                <div key={s.id} style={{ display: "flex", alignItems: "center", gap: 8, fontSize: 12, color: T.textSub }}>
                  <FmBadge cat={s.exercise.category} label={s.exercise.name} />
                  <span>#{s.setNumber}</span>
                  {s.reps   != null && <span>{s.reps} reps</span>}
                  {s.weight != null && <span>· {s.weight} kg</span>}
                </div>
              ))}
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

// ─── History Card ──────────────────────────────────────────────────────────────
function HistoryCard({ w }: { w: WorkoutSession }) {
  const [open, setOpen] = useState(false);
  const dur = w.finishedAt
    ? Math.round((new Date(w.finishedAt).getTime() - new Date(w.startedAt).getTime()) / 60_000)
    : null;
  const uniqueEx = [...new Map(w.sets.map((s) => [s.exercise.id, s.exercise])).values()];
  const cats = [...new Set(uniqueEx.map((e) => e.category))];
  const catColor = CAT_COLOR[cats[0]] ?? T.accent;

  return (
    <div style={{ background: T.bgCard, borderRadius: 14, border: `1px solid ${T.border}`, overflow: "hidden" }}>
      <div
        onClick={() => setOpen((o) => !o)}
        style={{ padding: "14px 16px", display: "flex", alignItems: "center", gap: 12, cursor: "pointer" }}
      >
        <div style={{ width: 40, height: 40, borderRadius: 11, flexShrink: 0, background: catColor + "15", display: "flex", alignItems: "center", justifyContent: "center" }}>
          <Icon.Dumbbell s={17} c={catColor} />
        </div>
        <div style={{ flex: 1, minWidth: 0 }}>
          <div style={{ display: "flex", alignItems: "center", gap: 6, marginBottom: 3 }}>
            <span style={{ fontFamily: "var(--font-dm-sans, sans-serif)", fontSize: 14, fontWeight: 600, color: T.textPrimary }}>
              {format(new Date(w.startedAt), "EEE, MMM d")}
            </span>
            {dur != null && (
              <span style={{ display: "flex", alignItems: "center", gap: 3, fontSize: 11, color: T.textMuted }}>
                <Icon.Timer s={11} c={T.textMuted} />{dur}m
              </span>
            )}
          </div>
          <div style={{ display: "flex", flexWrap: "wrap", gap: 3 }}>
            {uniqueEx.slice(0, 2).map((ex) => (
              <FmBadge key={ex.id} cat={ex.category} label={ex.name.slice(0, 12)} />
            ))}
            {uniqueEx.length > 2 && <span style={{ fontSize: 10, color: T.textMuted, alignSelf: "center" }}>+{uniqueEx.length - 2} more</span>}
          </div>
        </div>
        <div style={{ display: "flex", flexDirection: "column", alignItems: "flex-end", gap: 3, marginRight: 4 }}>
          <span style={{ fontFamily: "var(--font-barlow-condensed, sans-serif)", fontSize: 20, fontWeight: 900, color: T.textPrimary }}>{w.sets.length}</span>
          <span style={{ fontSize: 10, color: T.textMuted }}>sets</span>
        </div>
        <Icon.ChevDown s={14} c={T.textMuted} />
      </div>

      {open && w.sets.length > 0 && (
        <div style={{ padding: "0 16px 14px", borderTop: `1px solid ${T.borderLight}` }}>
          <div style={{ paddingTop: 12, display: "flex", flexDirection: "column", gap: 5 }}>
            {w.sets.map((s) => (
              <div key={s.id} style={{ display: "flex", alignItems: "center", gap: 8, fontSize: 12, color: T.textSub }}>
                <FmBadge cat={s.exercise.category} label={s.exercise.name} />
                <span style={{ color: T.textMuted }}>#{s.setNumber}</span>
                {s.reps   != null && <span>{s.reps} reps</span>}
                {s.weight != null && <span>· {s.weight}kg</span>}
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  );
}

// ─── Page ──────────────────────────────────────────────────────────────────────
export default function WorkoutsPage() {
  const qc = useQueryClient();
  const [pickingExercise, setPickingExercise] = useState(false);
  const [startExerciseId, setStartExerciseId] = useState("");

  const { lang } = useLang();
  const t = useT();

  const { data: workoutsData, isLoading, isFetching } = useQuery({
    queryKey: ["workouts"],
    queryFn: getWorkouts,
  });
  const workouts: WorkoutSession[] = workoutsData ?? [];

  const { data: exData } = useQuery({
    queryKey: ["exercises-all", lang],
    queryFn: () => getExercises({ limit: 100, lang }),
    staleTime: Infinity,
    enabled: pickingExercise,
  });
  const exercises = (exData?.items ?? []).map((ex) => ({
    ...ex,
    name: lang === "ru" ? (ex.nameRu ?? ex.name) : ex.name,
  }));

  const { mutate: start, isPending: starting } = useMutation({
    mutationFn: () => startWorkout(),
    onSuccess: () => {
      setPickingExercise(false);
      setStartExerciseId("");
      qc.invalidateQueries({ queryKey: ["workouts"] });
    },
  });

  if (isLoading) return <FmPageLoader />;

  const ongoing = workouts.find((w) => !w.finishedAt);
  const history  = workouts.filter((w) => !!w.finishedAt);

  return (
    <div style={{ background: T.bg, minHeight: "100%", display: "flex", flexDirection: "column" }}>
      <AppHeader
        title={t.workouts.title}
        right={
          !ongoing ? (
            <FmBtn size="sm" loading={starting || isFetching} onClick={() => setPickingExercise(true)}>
              <Icon.Plus s={14} c="#0d0d12" /> {t.workouts.start}
            </FmBtn>
          ) : undefined
        }
      />

      {/* Exercise picker modal before starting */}
      {pickingExercise && !ongoing && (
        <div style={{
          position: "fixed", inset: 0, zIndex: 100,
          background: "rgba(0,0,0,0.7)", display: "flex", alignItems: "center", justifyContent: "center",
          padding: 20,
        }}
          onClick={(e) => { if (e.target === e.currentTarget) { setPickingExercise(false); setStartExerciseId(""); } }}
        >
          <div style={{ background: T.bgCard, borderRadius: 18, border: `1px solid ${T.border}`, padding: 24, width: "100%", maxWidth: 380, display: "flex", flexDirection: "column", gap: 18 }}>
            <div>
              <p style={{ fontFamily: "var(--font-barlow-condensed, sans-serif)", fontSize: 22, fontWeight: 900, textTransform: "uppercase", color: T.textPrimary, marginBottom: 4 }}>
                {t.workouts.newWorkout}
              </p>
              <p style={{ fontFamily: "var(--font-dm-sans, sans-serif)", fontSize: 13, color: T.textSub }}>
                {t.workouts.newWorkoutBody}
              </p>
            </div>
            <FmExercisePicker value={startExerciseId} onChange={setStartExerciseId} exercises={exercises} />
            <div style={{ display: "flex", gap: 10 }}>
              <FmBtn variant="ghost" style={{ flex: 1 }} onClick={() => { setPickingExercise(false); setStartExerciseId(""); }}>
                {t.workouts.cancel}
              </FmBtn>
              <FmBtn style={{ flex: 1 }} disabled={!startExerciseId} loading={starting} onClick={() => start()}>
                {t.workouts.start}
              </FmBtn>
            </div>
          </div>
        </div>
      )}

      <div style={{ flex: 1, padding: "16px 20px", display: "flex", flexDirection: "column", gap: 14 }}>
        {ongoing && (
          <SetLogger
            key={ongoing.id}
            session={ongoing}
            onDone={() => qc.invalidateQueries({ queryKey: ["workouts"] })}
          />
        )}

        {!ongoing && history.length === 0 ? (
          <FmEmpty
            icon={Icon.Dumbbell}
            title="No workouts yet"
            body="Start your first session to begin tracking"
            action={
              <FmBtn size="lg" loading={starting || isFetching} onClick={() => setPickingExercise(true)}>
                <Icon.Plus s={18} c="#0d0d12" /> Start First Workout
              </FmBtn>
            }
          />
        ) : history.length > 0 ? (
          <>
            <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between" }}>
              <span style={{ fontFamily: "var(--font-barlow-condensed, sans-serif)", fontSize: 12, fontWeight: 700, letterSpacing: "0.1em", textTransform: "uppercase", color: T.textSub }}>
                History
              </span>
              <span style={{ fontSize: 11, color: T.textMuted }}>{history.length} sessions</span>
            </div>
            {history.map((w) => <HistoryCard key={w.id} w={w} />)}
          </>
        ) : null}
      </div>
    </div>
  );
}

"use client";

import { useState, useEffect } from "react";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { format } from "date-fns";
import {
  getWorkouts, startWorkout, finishWorkout, logSets,
  type WorkoutSession, type CreateSetInput,
} from "@/features/workouts/workouts.api";
import { getExercises } from "@/features/exercises/exercises.api";
import { T, CAT_COLOR, Icon, FmBadge, FmBtn, FmPageLoader, FmEmpty, FmExercisePicker, AppHeader } from "@/components/fm";
import { useLang, useT } from "@/lib/lang-context";

// ─── Elapsed timer hook ────────────────────────────────────────────────────────
function useElapsed(startedAt: string) {
  const [elapsed, setElapsed] = useState(() =>
    Math.floor((Date.now() - new Date(startedAt).getTime()) / 1000)
  );
  useEffect(() => {
    const t = setInterval(() => setElapsed((s) => s + 1), 1000);
    return () => clearInterval(t);
  }, []);
  const mm = String(Math.floor(elapsed / 60)).padStart(2, "0");
  const ss = String(elapsed % 60).padStart(2, "0");
  return `${mm}:${ss}`;
}

// ─── Set Logger ────────────────────────────────────────────────────────────────
function SetLogger({ session, onDone }: { session: WorkoutSession; onDone: () => void }) {
  const qc = useQueryClient();
  const elapsed = useElapsed(session.startedAt);
  const { lang } = useLang();
  const t = useT();

  const [exerciseId, setExerciseId] = useState("");
  const [rows, setRows] = useState<Omit<CreateSetInput, "exerciseId">[]>([
    { setNumber: 1, reps: undefined, weight: undefined },
  ]);

  const { data: exData } = useQuery({
    queryKey: ["exercises-all", lang],
    queryFn: () => getExercises({ limit: 100, lang }),
    staleTime: Infinity,
  });
  const exercises = (exData?.items ?? []).map((ex) => ({
    ...ex,
    name: lang === "ru" ? (ex.nameRu ?? ex.name) : ex.name,
  }));

  function handleExerciseChange(id: string) {
    setExerciseId(id);
    const existing = session.sets.filter((s) => s.exercise.id === id).length;
    setRows([{ setNumber: existing + 1, reps: undefined, weight: undefined }]);
  }

  const { mutate: log, isPending: logging } = useMutation({
    mutationFn: () => logSets(session.id, rows.map((r) => ({ ...r, exerciseId }))),
    onSuccess: (data) => {
      const maxSet = data.length > 0 ? Math.max(...data.map((s) => s.setNumber)) : rows.length;
      setRows([{ setNumber: maxSet + 1, reps: undefined, weight: undefined }]);
      qc.invalidateQueries({ queryKey: ["workouts"] });
      qc.invalidateQueries({ queryKey: ["dashboard-stats"] });
    },
  });

  const { mutate: finish, isPending: finishing } = useMutation({
    mutationFn: () => finishWorkout(session.id),
    onSuccess: () => {
      qc.invalidateQueries({ queryKey: ["workouts"] });
      qc.invalidateQueries({ queryKey: ["dashboard-stats"] });
      onDone();
    },
  });

  function addRow() {
    const existing = session.sets.filter((s) => s.exercise.id === exerciseId).length;
    setRows((r) => [...r, { setNumber: existing + r.length + 1, reps: undefined, weight: undefined }]);
  }

  function updateRow(i: number, key: "reps" | "weight", val: string) {
    setRows((r) => r.map((row, idx) =>
      idx === i ? { ...row, [key]: val === "" ? undefined : Number(val) } : row
    ));
  }

  const canLog = !!exerciseId && rows.some((r) => r.reps != null || r.weight != null);

  return (
    <div style={{ background: T.bgCard, borderRadius: 16, border: `1px solid ${T.border}`, overflow: "hidden" }}>
      {/* Session header */}
      <div style={{ padding: "14px 18px", borderBottom: `1px solid ${T.border}`, display: "flex", alignItems: "center", justifyContent: "space-between" }}>
        <div>
          <div style={{ display: "flex", alignItems: "center", gap: 6, marginBottom: 2 }}>
            <div style={{ width: 8, height: 8, borderRadius: "50%", background: T.success, animation: "fm-pulse 2s infinite" }} />
            <span style={{ fontFamily: "var(--font-barlow-condensed, sans-serif)", fontSize: 13, fontWeight: 700, color: T.success, textTransform: "uppercase", letterSpacing: "0.08em" }}>
              {t.workouts.active}
            </span>
          </div>
          <span style={{ fontFamily: "var(--font-barlow-condensed, sans-serif)", fontSize: 26, fontWeight: 900, color: T.textPrimary, letterSpacing: "-0.01em" }}>
            {elapsed}
          </span>
        </div>
        <FmBtn variant="danger" size="sm" loading={finishing} onClick={() => finish()}>
          {t.workouts.finish}
        </FmBtn>
      </div>

      <div style={{ padding: "14px 18px", display: "flex", flexDirection: "column", gap: 14 }}>
        <FmExercisePicker value={exerciseId} onChange={handleExerciseChange} exercises={exercises} />

        {exerciseId && (
          <div>
            <div style={{ display: "grid", gridTemplateColumns: "36px 1fr 1fr", gap: 6, marginBottom: 6 }}>
              {[t.workouts.setCol, t.workouts.repsCol, "kg"].map((h) => (
                <span key={h} style={{ textAlign: "center", fontSize: 10, color: T.textMuted, fontFamily: "var(--font-barlow-condensed, sans-serif)", fontWeight: 700, letterSpacing: "0.08em", textTransform: "uppercase" }}>
                  {h}
                </span>
              ))}
            </div>
            {rows.map((row, i) => (
              <div key={i} style={{ display: "grid", gridTemplateColumns: "36px 1fr 1fr", gap: 6, marginBottom: 6 }}>
                <div style={{ height: 42, background: T.bgInput, borderRadius: 8, display: "flex", alignItems: "center", justifyContent: "center" }}>
                  <span style={{ fontFamily: "var(--font-barlow-condensed, sans-serif)", fontSize: 15, fontWeight: 800, color: T.textSub }}>{row.setNumber}</span>
                </div>
                <input type="number" min={0} placeholder="—" value={row.reps ?? ""} onChange={(e) => updateRow(i, "reps", e.target.value)} style={{ height: 42, background: T.bgInput, border: `1.5px solid ${T.border}`, borderRadius: 8, textAlign: "center", color: T.textPrimary, fontFamily: "var(--font-barlow-condensed, sans-serif)", fontSize: 17, fontWeight: 700, outline: "none" }} />
                <input type="number" min={0} step={0.5} placeholder="—" value={row.weight ?? ""} onChange={(e) => updateRow(i, "weight", e.target.value)} style={{ height: 42, background: T.bgInput, border: `1.5px solid ${T.border}`, borderRadius: 8, textAlign: "center", color: T.textPrimary, fontFamily: "var(--font-barlow-condensed, sans-serif)", fontSize: 17, fontWeight: 700, outline: "none" }} />
              </div>
            ))}
            <button type="button" onClick={addRow} disabled={!exerciseId} style={{ background: "none", border: "none", color: T.accent, fontFamily: "var(--font-dm-sans, sans-serif)", fontSize: 12, fontWeight: 500, cursor: "pointer", padding: "2px 0", opacity: exerciseId ? 1 : 0.4 }}>
              {t.workouts.addSet}
            </button>
          </div>
        )}

        <FmBtn onClick={() => log()} disabled={!canLog} loading={logging} style={{ width: "100%" }}>
          {t.workouts.logSets}
        </FmBtn>

        {session.sets.length > 0 && (
          <div style={{ borderTop: `1px solid ${T.border}`, paddingTop: 12 }}>
            <span style={{ fontSize: 10, fontFamily: "var(--font-barlow-condensed, sans-serif)", fontWeight: 700, textTransform: "uppercase", letterSpacing: "0.08em", color: T.textMuted }}>
              {t.workouts.logged} · {session.sets.length}
            </span>
            <div style={{ marginTop: 8, display: "flex", flexDirection: "column", gap: 5 }}>
              {session.sets.map((s) => (
                <div key={s.id} style={{ display: "flex", alignItems: "center", gap: 8, fontSize: 12, color: T.textSub }}>
                  <FmBadge cat={s.exercise.category} label={s.exercise.name} />
                  <span>#{s.setNumber}</span>
                  {s.reps   != null && <span>{s.reps} reps</span>}
                  {s.weight != null && <span>· {s.weight} kg</span>}
                </div>
              ))}
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

// ─── History Card ──────────────────────────────────────────────────────────────
function HistoryCard({ w }: { w: WorkoutSession }) {
  const [open, setOpen] = useState(false);
  const dur = w.finishedAt
    ? Math.round((new Date(w.finishedAt).getTime() - new Date(w.startedAt).getTime()) / 60_000)
    : null;
  const uniqueEx = [...new Map(w.sets.map((s) => [s.exercise.id, s.exercise])).values()];
  const cats = [...new Set(uniqueEx.map((e) => e.category))];
  const catColor = CAT_COLOR[cats[0]] ?? T.accent;

  return (
    <div style={{ background: T.bgCard, borderRadius: 14, border: `1px solid ${T.border}`, overflow: "hidden" }}>
      <div
        onClick={() => setOpen((o) => !o)}
        style={{ padding: "14px 16px", display: "flex", alignItems: "center", gap: 12, cursor: "pointer" }}
      >
        <div style={{ width: 40, height: 40, borderRadius: 11, flexShrink: 0, background: catColor + "15", display: "flex", alignItems: "center", justifyContent: "center" }}>
          <Icon.Dumbbell s={17} c={catColor} />
        </div>
        <div style={{ flex: 1, minWidth: 0 }}>
          <div style={{ display: "flex", alignItems: "center", gap: 6, marginBottom: 3 }}>
            <span style={{ fontFamily: "var(--font-dm-sans, sans-serif)", fontSize: 14, fontWeight: 600, color: T.textPrimary }}>
              {format(new Date(w.startedAt), "EEE, MMM d")}
            </span>
            {dur != null && (
              <span style={{ display: "flex", alignItems: "center", gap: 3, fontSize: 11, color: T.textMuted }}>
                <Icon.Timer s={11} c={T.textMuted} />{dur}m
              </span>
            )}
          </div>
          <div style={{ display: "flex", flexWrap: "wrap", gap: 3 }}>
            {uniqueEx.slice(0, 2).map((ex) => (
              <FmBadge key={ex.id} cat={ex.category} label={ex.name.slice(0, 12)} />
            ))}
            {uniqueEx.length > 2 && <span style={{ fontSize: 10, color: T.textMuted, alignSelf: "center" }}>+{uniqueEx.length - 2} more</span>}
          </div>
        </div>
        <div style={{ display: "flex", flexDirection: "column", alignItems: "flex-end", gap: 3, marginRight: 4 }}>
          <span style={{ fontFamily: "var(--font-barlow-condensed, sans-serif)", fontSize: 20, fontWeight: 900, color: T.textPrimary }}>{w.sets.length}</span>
          <span style={{ fontSize: 10, color: T.textMuted }}>sets</span>
        </div>
        <Icon.ChevDown s={14} c={T.textMuted} />
      </div>

      {open && w.sets.length > 0 && (
        <div style={{ padding: "0 16px 14px", borderTop: `1px solid ${T.borderLight}` }}>
          <div style={{ paddingTop: 12, display: "flex", flexDirection: "column", gap: 5 }}>
            {w.sets.map((s) => (
              <div key={s.id} style={{ display: "flex", alignItems: "center", gap: 8, fontSize: 12, color: T.textSub }}>
                <FmBadge cat={s.exercise.category} label={s.exercise.name} />
                <span style={{ color: T.textMuted }}>#{s.setNumber}</span>
                {s.reps   != null && <span>{s.reps} reps</span>}
                {s.weight != null && <span>· {s.weight}kg</span>}
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  );
}

// ─── Page ──────────────────────────────────────────────────────────────────────
export default function WorkoutsPage() {
  const qc = useQueryClient();
  const [pickingExercise, setPickingExercise] = useState(false);
  const [startExerciseId, setStartExerciseId] = useState("");

  const { lang } = useLang();
  const t = useT();

  const { data: workoutsData, isLoading, isFetching } = useQuery({
    queryKey: ["workouts"],
    queryFn: getWorkouts,
  });
  const workouts: WorkoutSession[] = workoutsData ?? [];

  const { data: exData } = useQuery({
    queryKey: ["exercises-all", lang],
    queryFn: () => getExercises({ limit: 100, lang }),
    staleTime: Infinity,
    enabled: pickingExercise,
  });
  const exercises = (exData?.items ?? []).map((ex) => ({
    ...ex,
    name: lang === "ru" ? (ex.nameRu ?? ex.name) : ex.name,
  }));

  const { mutate: start, isPending: starting } = useMutation({
    mutationFn: () => startWorkout(),
    onSuccess: () => {
      setPickingExercise(false);
      setStartExerciseId("");
      qc.invalidateQueries({ queryKey: ["workouts"] });
    },
  });

  if (isLoading) return <FmPageLoader />;

  const ongoing = workouts.find((w) => !w.finishedAt);
  const history  = workouts.filter((w) => !!w.finishedAt);

  return (
    <div style={{ background: T.bg, minHeight: "100%", display: "flex", flexDirection: "column" }}>
      <AppHeader
        title={t.workouts.title}
        right={
          !ongoing ? (
            <FmBtn size="sm" loading={starting || isFetching} onClick={() => setPickingExercise(true)}>
              <Icon.Plus s={14} c="#0d0d12" /> {t.workouts.start}
            </FmBtn>
          ) : undefined
        }
      />

      {/* Exercise picker modal before starting */}
      {pickingExercise && !ongoing && (
        <div style={{
          position: "fixed", inset: 0, zIndex: 100,
          background: "rgba(0,0,0,0.7)", display: "flex", alignItems: "center", justifyContent: "center",
          padding: 20,
        }}
          onClick={(e) => { if (e.target === e.currentTarget) { setPickingExercise(false); setStartExerciseId(""); } }}
        >
          <div style={{ background: T.bgCard, borderRadius: 18, border: `1px solid ${T.border}`, padding: 24, width: "100%", maxWidth: 380, display: "flex", flexDirection: "column", gap: 18 }}>
            <div>
              <p style={{ fontFamily: "var(--font-barlow-condensed, sans-serif)", fontSize: 22, fontWeight: 900, textTransform: "uppercase", color: T.textPrimary, marginBottom: 4 }}>
                {t.workouts.newWorkout}
              </p>
              <p style={{ fontFamily: "var(--font-dm-sans, sans-serif)", fontSize: 13, color: T.textSub }}>
                {t.workouts.newWorkoutBody}
              </p>
            </div>
            <FmExercisePicker value={startExerciseId} onChange={setStartExerciseId} exercises={exercises} />
            <div style={{ display: "flex", gap: 10 }}>
              <FmBtn variant="ghost" style={{ flex: 1 }} onClick={() => { setPickingExercise(false); setStartExerciseId(""); }}>
                {t.workouts.cancel}
              </FmBtn>
              <FmBtn style={{ flex: 1 }} disabled={!startExerciseId} loading={starting} onClick={() => start()}>
                {t.workouts.start}
              </FmBtn>
            </div>
          </div>
        </div>
      )}

      <div style={{ flex: 1, padding: "16px 20px", display: "flex", flexDirection: "column", gap: 14 }}>
        {ongoing && (
          <SetLogger
            key={ongoing.id}
            session={ongoing}
            onDone={() => qc.invalidateQueries({ queryKey: ["workouts"] })}
          />
        )}

        {!ongoing && history.length === 0 ? (
          <FmEmpty
            icon={Icon.Dumbbell}
            title={t.workouts.noWorkouts}
            body={t.workouts.noWorkoutsBody}
            action={
              <FmBtn size="lg" loading={starting || isFetching} onClick={() => setPickingExercise(true)}>
                <Icon.Plus s={18} c="#0d0d12" /> {t.workouts.startFirstWorkout}
              </FmBtn>
            }
          />
        ) : history.length > 0 ? (
          <>
            <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between" }}>
              <span style={{ fontFamily: "var(--font-barlow-condensed, sans-serif)", fontSize: 12, fontWeight: 700, letterSpacing: "0.1em", textTransform: "uppercase", color: T.textSub }}>
                History
              </span>
              <span style={{ fontSize: 11, color: T.textMuted }}>{history.length} sessions</span>
            </div>
            {history.map((w) => <HistoryCard key={w.id} w={w} />)}
          </>
        ) : null}
      </div>
    </div>
  );
}

import {
  Body, Controller, Get, Param, Patch, Post, UseGuards,
} from "@nestjs/common";
import { ApiBearerAuth, ApiOperation, ApiTags } from "@nestjs/swagger";
import { WorkoutsService } from "./workouts.service";
import { FinishWorkoutDto, LogSetsDto, StartWorkoutDto } from "./workouts.dto";
import { JwtGuard } from "../common/guards/jwt.guard";
import { CurrentUser } from "../common/decorators/current-user.decorator";
import { User } from "@fitness-app/database";

@ApiTags("workouts")
@ApiBearerAuth()
@UseGuards(JwtGuard)
@Controller("workouts")
export class WorkoutsController {
  constructor(private readonly svc: WorkoutsService) {}

  @Post()
  @ApiOperation({ summary: "Start a new workout session" })
  start(@CurrentUser() user: User, @Body() dto: StartWorkoutDto) {
    return this.svc.start(user.id, dto);
  }

  @Get()
  @ApiOperation({ summary: "List recent workout sessions" })
  findAll(@CurrentUser() user: User) {
    return this.svc.findAll(user.id);
  }

  @Get(":id")
  @ApiOperation({ summary: "Get single workout session" })
  findOne(@CurrentUser() user: User, @Param("id") id: string) {
    return this.svc.findOne(user.id, id);
  }

  @Patch(":id/finish")
  @ApiOperation({ summary: "Finish a workout session" })
  finish(
    @CurrentUser() user: User,
    @Param("id") id: string,
    @Body() dto: FinishWorkoutDto,
  ) {
    return this.svc.finish(user.id, id, dto);
  }

  @Patch(":id/notes")
  @ApiOperation({ summary: "Update session notes" })
  updateNotes(
    @CurrentUser() user: User,
    @Param("id") id: string,
    @Body() dto: FinishWorkoutDto,
  ) {
    return this.svc.updateNotes(user.id, id, dto);
  }

  @Post(":id/sets")
  @ApiOperation({ summary: "Log (upsert) sets for a session" })
  logSets(
    @CurrentUser() user: User,
    @Param("id") id: string,
    @Body() dto: LogSetsDto,
  ) {
    return this.svc.logSets(user.id, id, dto);
  }
}

