import { Injectable, NotFoundException, ForbiddenException } from "@nestjs/common";
import { PrismaService } from "../common/prisma/prisma.service";
import { StartWorkoutDto, FinishWorkoutDto, LogSetsDto } from "./workouts.dto";

@Injectable()
export class WorkoutsService {
  constructor(private readonly prisma: PrismaService) {}

  async start(userId: string, dto: StartWorkoutDto) {
    return this.prisma.workoutSession.create({
      data: { userId, notes: dto.notes },
      include: { sets: { include: { exercise: true } } },
    });
  }

  async findAll(userId: string) {
    return this.prisma.workoutSession.findMany({
      where: { userId },
      orderBy: { startedAt: "desc" },
      take: 20,
      include: {
        sets: {
          include: { exercise: { select: { id: true, name: true, category: true } } },
          orderBy: [{ setNumber: "asc" }],
        },
      },
    });
  }

  async findOne(userId: string, id: string) {
    const session = await this.prisma.workoutSession.findUnique({
      where: { id },
      include: {
        sets: {
          include: { exercise: true },
          orderBy: [{ setNumber: "asc" }],
        },
      },
    });
    if (!session) throw new NotFoundException();
    if (session.userId !== userId) throw new ForbiddenException();
    return session;
  }

  async finish(userId: string, id: string, dto: FinishWorkoutDto) {
    await this.findOne(userId, id); // auth check
    return this.prisma.workoutSession.update({
      where: { id },
      data: { finishedAt: new Date(), ...(dto.notes !== undefined && { notes: dto.notes }) },
      include: { sets: { include: { exercise: true } } },
    });
  }

  async updateNotes(userId: string, id: string, dto: FinishWorkoutDto) {
    await this.findOne(userId, id); // auth check
    return this.prisma.workoutSession.update({
      where: { id },
      data: { notes: dto.notes ?? null },
    });
  }

  async logSets(userId: string, sessionId: string, dto: LogSetsDto) {
    await this.findOne(userId, sessionId); // auth check
    // Upsert each set by (sessionId, exerciseId, setNumber)
    const created = await this.prisma.$transaction(
      dto.sets.map((s) =>
        this.prisma.workoutSet.upsert({
          where: {
            sessionId_exerciseId_setNumber: {
              sessionId,
              exerciseId: s.exerciseId,
              setNumber: s.setNumber,
            },
          },
          create: {
            sessionId,
            exerciseId: s.exerciseId,
            setNumber: s.setNumber,
            reps: s.reps,
            weight: s.weight,
            duration: s.duration,
            rpe: s.rpe,
          },
          update: {
            reps: s.reps,
            weight: s.weight,
            duration: s.duration,
            rpe: s.rpe,
          },
          include: { exercise: { select: { id: true, name: true } } },
        }),
      ),
    );
    return created;
  }
}

